files.content:
* {
  box-sizing: border-box;
}

html {
  block-size: 100%;
}

body {
  display: grid;
  place-items: center;
  min-width: 550px;
  margin: 0;
  padding: 50px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
  block-size: 100%;
}

.wrapper {
  border: 1px solid #000;
  padding: 25px;
  background-color: #6dc1fd;
  max-inline-size: 850px;
  inline-size: 80%;
  min-inline-size: 450px;
}

p {
  margin-block-start: 0;
}

dialog {
  border-width: 1px;
  max-inline-size: 550px;
  inline-size: 80%;
  min-inline-size: 250px;
}

h2 {
  margin-block-start: 0;
  font-weight: 800;
  font-size: 22px;
  text-transform: uppercase;
}

form {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

input {
  border: 1px solid #000;
  padding: 10px 15px;
  font-family: inherit;
  font-size: inherit;
  background-color: transparent;
}

input::placeholder {
  color: rgb(0 0 0 / 0.6);
}

input:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}

button {
  border: 1px solid #000;
  padding: 10px 65px;
  color: #000;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-transform: uppercase;
  background-color: #ffc802;
}

button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

button:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}

dialog::backdrop {
  background-color: rgb(0 0 0 / 0.3);
  backdrop-filter: blur(7px);
}
